 if(key==='rotation')return o.type==='icon'?isBossObject(o)||['距離減衰','フレア','ターゲット青','ロックオン赤','ロックオン紫','ダイブボム','ターゲット赤','ターゲット紫'].includes(o.iconName):shape;
